import{c as t,Q as o,j as a,m as r}from"./chunks/framework.BPKcPtvA.js";const g=JSON.parse('{"title":"Web Push notifications","description":"","frontmatter":{},"headers":[],"relativePath":"notifications.md","filePath":"notifications.md","lastUpdated":1789499754000}'),s={name:"notifications.md"};function n(i,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="web-push-notifications" tabindex="-1">Web Push notifications <a class="header-anchor" href="#web-push-notifications" aria-label="Permalink to &quot;Web Push notifications&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Enrollment ships; automatic notifications don&#39;t yet</p><p>You can enrol a browser, manage the enrolled devices and send yourself a test notification. <strong>Nothing sends a push automatically</strong> — no new-article trigger exists, so once enrolled you will only ever receive the test message. Enrol if you want to verify the plumbing on your deployment; don&#39;t expect to be told about new articles by it yet.</p><p>For actually noticing new articles today, see <a href="#what-tells-you-about-new-articles-today">what does tell you</a>.</p></div><h2 id="what-works-today" tabindex="-1">What works today <a class="header-anchor" href="#what-works-today" aria-label="Permalink to &quot;What works today&quot;">​</a></h2><p>From <strong>Settings → Notifications</strong>:</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Enable</strong></td><td>Enrols this browser (or installed PWA). Asks for the browser&#39;s notification permission, subscribes with the server&#39;s VAPID key, and registers the subscription against your account.</td></tr><tr><td><strong>Turn off</strong></td><td>Appears in place of <em>Enable</em> once this browser is enrolled. Unsubscribes this browser and removes its entry in one step.</td></tr><tr><td><strong>Send test</strong></td><td>Fires a sample notification to every device registered to your account. This is the only thing that sends a push.</td></tr><tr><td><strong>Registered devices</strong></td><td>Every browser enrolled by your account, by user-agent. <strong>Revoke</strong> removes one; revoking the device you&#39;re on also unsubscribes it locally.</td></tr></tbody></table><p>Enrolment is <strong>per browser</strong>, not per account — each browser or installed PWA you want notified has to be enabled from that browser.</p><h2 id="what-doesn-t-work-yet" tabindex="-1">What doesn&#39;t work yet <a class="header-anchor" href="#what-doesn-t-work-yet" aria-label="Permalink to &quot;What doesn&#39;t work yet&quot;">​</a></h2><ul><li><strong>No automatic notifications.</strong> Nothing in the poller, ingest path or filters triggers a push. The delivery machinery is complete and tested — the trigger simply isn&#39;t written.</li><li><strong>No <code>notify</code> filter action.</strong> The rules engine can tag, star, mark read and mute; it cannot send a notification.</li></ul><h2 id="what-tells-you-about-new-articles-today" tabindex="-1">What tells you about new articles today <a class="header-anchor" href="#what-tells-you-about-new-articles-today" aria-label="Permalink to &quot;What tells you about new articles today&quot;">​</a></h2><ul><li>A <strong>favicon dot</strong> and a <code>(N) Ember</code> page-title prefix while the tab is open.</li><li>An <strong>OS-level numeric badge</strong> on the app icon when installed as a PWA.</li><li>The optional <strong><a href="/configuration#optional-env-vars">daily digest email</a></strong>.</li></ul><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li><strong>A trusted TLS certificate.</strong> Service workers refuse to register over self-signed certificates, so Web Push, the offline cache and PWA install all fail together on a homelab deployment using Caddy&#39;s <code>tls internal</code>. Use a real certificate — the DNS-01 route works for LAN-only hosts that can&#39;t answer an HTTP-01 challenge. See <a href="/caddy-hardening">Hardening Caddy</a>.</li><li>Nothing to configure to switch the feature on: the VAPID keypair is generated on first start and persisted server-side. If key generation fails, the push endpoints return <code>503</code> and the rest of Ember is unaffected.</li></ul><h2 id="operator-notes" tabindex="-1">Operator notes <a class="header-anchor" href="#operator-notes" aria-label="Permalink to &quot;Operator notes&quot;">​</a></h2><ul><li><strong>Deliverability contact.</strong> Push services want a contact address for the sender, taken from <code>EMBER_SMTP_FROM</code>. When that isn&#39;t set Ember falls back to <code>mailto:admin@localhost</code> and logs a warning at startup — harmless for a private instance, but push services may deprioritise an unidentified sender.</li><li><strong>No third-party push provider.</strong> Ember signs and encrypts each message with its own VAPID keypair; there&#39;s no OneSignal-style intermediary holding your data. Delivery still goes through the browser vendor&#39;s push service (Google, Mozilla, Apple), as the Web Push standard requires — those services relay an encrypted payload they cannot read.</li><li><strong>Dead subscriptions clean themselves up.</strong> A push service replying <code>410 Gone</code> causes Ember to drop that subscription; the test-send response reports how many were sent and how many were removed.</li></ul>',14)])])}const p=t(s,[["render",n]]);export{g as __pageData,p as default};
